function getP(p,s,c,d){if(p&&p[s]!==undefined)return p[s];if(p&&p[c]!==undefined)return p[c];return d;}
const DT=0.1;
const CAP=1000;
exports.init=(params,rng)=>{const N0=getP(params,'initial_prey','initialPrey',40);const P0=getP(params,'initial_predator','initialPredator',9);return{N:N0,P:P0,t:0,historyN:[N0],historyP:[P0]};};
exports.step=(state,params,rng)=>{const r=getP(params,'prey_growth_rate','preyGrowthRate',0.5);const a=getP(params,'predation_rate','predationRate',0.02);const e=getP(params,'conversion_efficiency','conversionEfficiency',0.1);const m=getP(params,'predator_mortality','predatorMortality',0.2);let N=state.N;let P=state.P;function dNdt(N,P){return r*N - a*N*P;}
function dPdt(N,P){return e*a*N*P - m*P;}
let k1N=DT*dNdt(N,P);let k1P=DT*dPdt(N,P);let k2N=DT*dNdt(N+k1N/2,P+k1P/2);let k2P=DT*dPdt(N+k1N/2,P+k1P/2);let k3N=DT*dNdt(N+k2N/2,P+k2P/2);let k3P=DT*dPdt(N+k2N/2,P+k2P/2);let k4N=DT*dNdt(N+k3N,P+k3P);let k4P=DT*dPdt(N+k3N,P+k3P);let N2=N+(k1N+2*k2N+2*k3N+k4N)/6;let P2=P+(k1P+2*k2P+2*k3P+k4P)/6;if(!isFinite(N2)||N2<0.1)N2=0.1;if(!isFinite(P2)||P2<0.1)P2=0.1;if(N2>CAP)N2=CAP;if(P2>CAP)P2=CAP;state.historyN.push(N2);state.historyP.push(P2);return{N:N2,P:P2,t:state.t+1,historyN:state.historyN,historyP:state.historyP};};
exports.observe=(state,params)=>{const hN=state.historyN;const hP=state.historyP;const n=hN.length;if(n<10){return{mean_prey_population:hN[n-1]||0,mean_predator_population:hP[n-1]||0,prey_oscillation_amplitude:0,prey_to_predator_peak_lag:0,prey_predator_correlation_zero_lag:0};}
const start=Math.floor(n*0.5);const winN=hN.slice(start);const winP=hP.slice(start);const wn=winN.length;let sumN=0,sumP=0;for(let i=0;i<wn;i++){sumN+=winN[i];sumP+=winP[i];}
const meanN=sumN/wn;const meanP=sumP/wn;let varN=0;for(let i=0;i<wn;i++){const d=winN[i]-meanN;varN+=d*d;}
const stdN=Math.sqrt(varN/wn);const amp=meanN>0?stdN/meanN:0;function pearson(x,y){const nn=x.length;if(nn===0)return 0;let sx=0,sy=0;for(let i=0;i<nn;i++){sx+=x[i];sy+=y[i];}
const mx=sx/nn,my=sy/nn;let num=0,dx2=0,dy2=0;for(let i=0;i<nn;i++){const dx=x[i]-mx,dy=y[i]-my;num+=dx*dy;dx2+=dx*dx;dy2+=dy*dy;}
const den=Math.sqrt(dx2*dy2);if(den===0)return 0;return num/den;}
const corr0=pearson(winN,winP);let bestLag=0,bestCorr=-2;const maxLag=Math.min(150,wn-10);for(let lag=0;lag<=maxLag;lag++){const len=wn-lag;if(len<10)break;const aN=winN.slice(0,len);const aP=winP.slice(lag,len+lag);const c=pearson(aN,aP);if(c>bestCorr){bestCorr=c;bestLag=lag;}}
return{mean_prey_population:meanN,mean_predator_population:meanP,prey_oscillation_amplitude:amp,prey_to_predator_peak_lag:bestLag,prey_predator_correlation_zero_lag:corr0};};
exports.view=(state,params)=>{const N=state.N,P=state.P;const agents=[];const preyCount=Math.min(200,Math.max(0,Math.round(N)));const predCount=Math.min(100,Math.max(0,Math.round(P)));for(let i=0;i<preyCount;i++){const x=((i*0.137+state.t*0.005)%1);const y=((i*0.317+state.t*0.003)%1*0.6+0.2);const jx=(x+0.05*Math.sin(i*1.5+state.t*0.1)+1)%1;const jy=(y+0.05*Math.cos(i*2.3+state.t*0.1)+1)%1;agents.push({id:'prey_'+i,x:jx,y:jy,tint:0.35,sprite:'prey'});}
for(let i=0;i<predCount;i++){const x=((i*0.213+state.t*0.008+0.5)%1);const y=((i*0.451+state.t*0.004)%1*0.6+0.2);const jx=(x+0.05*Math.sin(i*1.7+state.t*0.12)+1)%1;const jy=(y+0.05*Math.cos(i*2.1+state.t*0.12)+1)%1;agents.push({id:'pred_'+i,x:jx,y:jy,tint:0.05,sprite:'predator'});}
return{kind:'population',agents:agents};};
